from pathlib import Path
import json,html
R=Path(__file__).resolve().parents[1]
def render():
 p=json.loads((R/'Docs/Development/IntegrationCandidateV1/review.json').read_bytes());e=html.escape
 cards=''.join('<section><h2>'+e(x['title'])+'</h2><p>'+e(x['description'])+'</p><details><summary>実際の画面</summary><a href="../../../'+e(x['image'])+'"><img src="../../../'+e(x['image'])+'" alt="'+e(x['title'])+'"></a></details></section>' for x in p['gameplay'])
 follow=p.get('followup');cards=('<section><h2>最新の追加実装</h2><p><a href="'+e(follow['path'])+'">'+e(follow['title'])+'</a></p><p>主家別軍務の全Core2392件・実表示復旧60組の結果とPR #2はこちら。</p></section>' if follow else '')+cards
 tests=p['core_tests'];core=str(tests.get('passed',tests.get('expected','')))+'件 '+('成功' if tests['status']=='PASSED' else '実行中')
 return '<!doctype html><html lang="ja"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>'+e(p['title'])+'</title><style>body{margin:0;background:#f3f1ec;color:#213039;font:16px/1.8 system-ui}main{max-width:1000px;margin:auto;padding:24px}section{background:#fff;border:1px solid #ccd5d1;border-radius:10px;padding:20px;margin:18px 0}h1{font-size:28px}h2{font-size:21px;margin:0}img{width:100%;height:auto}a{color:#146456;overflow-wrap:anywhere}.state{padding:7px 12px;background:#dfece4;display:inline-block;border-radius:7px}li{margin:5px 0}small{color:#51636c}@media(max-width:600px){main{padding:12px}section{padding:14px}}</style><main><h1>'+e(p['title'])+'</h1><div class="state">'+e(p['status'])+'</div><p>仕事 → 仕官 → 軍務 → 帰還 → 次の役目 → 辞去 → 再仕官</p><small>実行コードの基準 '+e(p['code_revision'][:12])+'。全国の完成ゲームではなく、一地域の武将プレイが一巡する開発版です。</small>'+cards+'<section><h2>統合確認</h2><ul><li>Core：'+e(core)+'</li><li>Gitに記録されたソースだけを別フォルダへ展開：Core/Gameのビルド成功</li><li>コード基準の既存GitHub CI：成功</li><li>実Godotで会話・移動・軍務と別プロセス保存復旧を確認</li><li>確認済みコードをPR #1でmainへ統合済み。design/foundationは変更なし</li></ul><p><a href="'+e(p['pull_request'])+'">レビュー用PR #1</a></p></section><section><h2>素材と残る範囲</h2><p>'+e(p['assets'])+'</p><ul>'+''.join('<li>'+e(x)+'</li>' for x in p['remaining'])+'</ul></section><section><h2>承認の境界</h2><p>'+e(p['approval'])+'</p><a href="../OPERATING_POLICY.md">既存の開発運用方針</a></section></main></html>'
if __name__=='__main__':(R/'Docs/Development/IntegrationCandidateV1/index.html').write_text(render(),encoding='utf8',newline='\n')
